import { readFileSync } from 'node:fs';
import { Router } from '@marmeon/router';
import { createTestApp } from '@marmeon/testing';
import { describe, expect, it } from 'vitest';
import application from '../../../bootstrap/app.ts';

// Generated by `marmeon make:auth` — the header's "Settings" link must be marked current on every settings page. The layout renders
// in the browser, so the test reads the link's `activeMatch` against the named GET routes under /settings/ of the real route table.

describe("the header's Settings link", { timeout: 30_000 }, () => {
  it('is marked current on every named settings page', async () => {
    const layout = readFileSync(new URL('./AppLayout.tsx', import.meta.url), 'utf8');
    const patterns = layout
      .match(/route="auth\.security" activeMatch=\{\[([^\]]*)\]\}/)?.[1]
      ?.match(/'[^']+'/g)
      ?.map((pattern) => pattern.slice(1, -1));
    expect(patterns, 'the Settings link has an activeMatch list').toBeDefined();

    const app = await createTestApp(application);
    const pages = app
      .make(Router)
      .routes.filter((route) => route.methods.includes('GET') && route.path.startsWith('/settings/') && route.routeName !== undefined)
      .map((route) => route.routeName!);
    expect(pages).toEqual(expect.arrayContaining(['auth.security', 'auth.two-factor', 'auth.passkeys', 'auth.tokens']));
    const matches = (name: string) => patterns!.some((pattern) => (pattern.endsWith('.*') ? name.startsWith(pattern.slice(0, -1)) : name === pattern));
    expect(pages.filter((name) => !matches(name)), 'settings pages the Settings link does not mark').toEqual([]);
  });
});
